package dev.unbox.unpvp;
import java.io.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.entity.EntityOtherPlayerMP;
import net.minecraft.entity.Entity;
import net.minecraft.entity.item.EntityArmorStand;
import net.minecraft.world.*;
import net.minecraft.util.ScreenShotHelper;
import com.mojang.authlib.GameProfile;
/** Fixed synthetic lobby, including visible players and holograms; never contacts a public server. */
final class LobbyProbe {
 private static final boolean CULL_TEST=Boolean.getBoolean("unpvp.test.occlusion");private static byte[] wallPixels;private static long hiddenBefore,namesBefore,measuredSkipped;private static boolean measuring;
 private static boolean launched,requested,prepared;private static volatile boolean serverReady;private static int scene;private static long since,last;private static final List<Long> frames=new ArrayList<>();private static final List<Entity> entities=new ArrayList<>();
 static void tick(){Minecraft mc=Minecraft.getMinecraft();if(!launched&&mc.currentScreen instanceof UiScreen){launched=true;mc.launchIntegratedServer("LobbyLab","Unbox Lobby Lab",new WorldSettings(42,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT));return;}if(mc.thePlayer==null||mc.theWorld==null)return;
  if(!requested){requested=true;mc.getIntegratedServer().addScheduledTask(()->{net.minecraft.world.WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);w.getGameRules().setOrCreateGameRule("doMobSpawning","false");w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");w.setWorldTime(6000);mc.getIntegratedServer().getConfigurationManager().getPlayerByUsername("UIPreview").setPositionAndUpdate(0,7,-15);serverReady=true;});return;}if(!serverReady)return;
  mc.gameSettings.limitFramerate=260;mc.gameSettings.enableVsync=false;mc.gameSettings.pauseOnLostFocus=false;mc.setIngameNotInFocus();mc.thePlayer.capabilities.isFlying=true;mc.thePlayer.motionY=0;mc.thePlayer.rotationYaw=mc.thePlayer.prevRotationYaw=0;mc.thePlayer.rotationPitch=mc.thePlayer.prevRotationPitch=8;
  if(!prepared){prepared=true;for(UiState.Module m:UiState.MODULES)UiState.set(m.id,LiveHud.IDS.contains(m.id));mc.displayGuiScreen(null);if(CULL_TEST){ModelOcclusion.disabled=true;for(UiState.Module m:UiState.MODULES)UiState.set(m.id,false);}since=System.nanoTime();}
  for(Entity e:entities){e.motionX=e.motionY=e.motionZ=0;if(e instanceof EntityOtherPlayerMP){EntityOtherPlayerMP p=(EntityOtherPlayerMP)e;p.rotationYaw=p.prevRotationYaw=180;p.rotationYawHead=p.prevRotationYawHead=180;}}
 }
 private static void populate(){Minecraft mc=Minecraft.getMinecraft();for(int i=0;i<64;i++){EntityOtherPlayerMP p=new EntityOtherPlayerMP(mc.theWorld,new GameProfile(new UUID(0,i+10),"LobbyPlayer"+i));p.setPosition((i%8-3.5)*1.7,4,1+i/8*1.7);p.prevPosX=p.lastTickPosX=p.posX;p.prevPosY=p.lastTickPosY=p.posY;p.prevPosZ=p.lastTickPosZ=p.posZ;mc.theWorld.addEntityToWorld(-2000-i,p);entities.add(p);}
  for(int i=0;i<48;i++){EntityArmorStand a=new EntityArmorStand(mc.theWorld,(i%8-3.5)*1.7,6+(i/8%3)*.3,1+i/8*2);a.setInvisible(true);a.setCustomNameTag("\u00a76\u00a7lPLAY GAME \u00a7r\u00a7f"+i+" \u00a7aRIGHT CLICK");a.setAlwaysRenderNameTag(true);a.prevPosX=a.lastTickPosX=a.posX;a.prevPosY=a.lastTickPosY=a.posY;a.prevPosZ=a.lastTickPosZ=a.posZ;mc.theWorld.addEntityToWorld(-3000-i,a);entities.add(a);}
 }
 private static void sample(Thread target,File dir){Thread sampler=new Thread(()->{try{Thread.sleep(1800);Map<String,Integer> calls=new HashMap<>();for(int i=0;i<300;i++){Set<String> seen=new HashSet<>();for(StackTraceElement e:target.getStackTrace())seen.add(e.getClassName()+"."+e.getMethodName());for(String name:seen)calls.put(name,calls.getOrDefault(name,0)+1);Thread.sleep(10);}List<Map.Entry<String,Integer>> rows=new ArrayList<>(calls.entrySet());rows.sort((a,b)->Integer.compare(b.getValue(),a.getValue()));try(PrintWriter out=new PrintWriter(new File(dir,"warmup-stacks.txt"))){for(Map.Entry<String,Integer> e:rows)out.println(e.getValue()+" "+e.getKey());}}catch(Exception e){e.printStackTrace();}},"Unbox lobby sampler");sampler.setDaemon(true);sampler.start();}
 static void frame(){if(since==0)return;Minecraft mc=Minecraft.getMinecraft();long now=System.nanoTime(),elapsed=now-since;if(last!=0&&elapsed>8_000_000_000L){if(!measuring){measuring=true;measuredSkipped=ModelOcclusion.skipped;}frames.add(now-last);}last=now;if(elapsed<16_000_000_000L)return;
  try{String name=(CULL_TEST?new String[]{"quiet","visible-off","visible-on","wall-off","wall-on","wall-no-names-diagnostic","wall-removed"}:new String[]{"quiet","players-holograms","players-no-labels-hud"})[scene];File dir=new File(mc.mcDataDir,"lobby-probe");dir.mkdirs();long total=0;for(long n:frames)total+=n;Collections.sort(frames);int n=frames.size();String line=String.format(Locale.ROOT,"%s,%d,%.3f,%.3f,%.3f,%.3f",name,n,n*1e9/total,frames.get(n/2)/1e6,frames.get((int)(n*.95))/1e6,frames.get((int)(n*.99))/1e6);try(PrintWriter out=new PrintWriter(new FileWriter(new File(dir,"frames.csv"),true))){out.println(line);}System.out.println("[unpvp-lobby] "+line);ScreenShotHelper.saveScreenshot(dir,name+".png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());if(org.lwjgl.opengl.GL11.glGetError()!=0)throw new IllegalStateException("GL error");
   if(CULL_TEST){
    System.out.println("[unpvp-occlusion] "+name+" queries="+ModelOcclusion.tested+" skipped="+ModelOcclusion.skipped+" names="+ModelOcclusion.names);
    if(scene==0){populate();}else if(scene==1){ModelOcclusion.disabled=false;}else if(scene==2){for(int i=0;i<8;i++)if(ModelOcclusion.hidden((EntityOtherPlayerMP)entities.get(i)))throw new IllegalStateException("Front-row model incorrectly hidden");ModelOcclusion.disabled=true;wall(true);}else if(scene==3){wallPixels=crop();ModelOcclusion.disabled=false;hiddenBefore=ModelOcclusion.skipped;namesBefore=ModelOcclusion.names;}else if(scene==4){if(ModelOcclusion.skipped-hiddenBefore<64||ModelOcclusion.names-namesBefore!=ModelOcclusion.skipped-hiddenBefore)throw new IllegalStateException("Occluded models/names not handled");if(!Arrays.equals(wallPixels,crop()))throw new IllegalStateException("Wall/name pixels differ with model culling");org.lwjgl.opengl.GL11.glPushMatrix();try{org.lwjgl.opengl.GL11.glRotatef(1,0,1,0);ModelOcclusion.begin(1);if(ModelOcclusion.active||ModelOcclusion.hidden((EntityOtherPlayerMP)entities.get(0)))throw new IllegalStateException("Camera transform reused stale occlusion");}finally{org.lwjgl.opengl.GL11.glPopMatrix();ModelOcclusion.end();}mc.gameSettings.hideGUI=true;}else if(scene==5){if(Arrays.equals(wallPixels,crop()))throw new IllegalStateException("Name preservation check contains no name pixels");mc.gameSettings.hideGUI=false;wall(false);hiddenBefore=ModelOcclusion.skipped;}else{if(ModelOcclusion.skipped!=measuredSkipped)throw new IllegalStateException("Models stayed hidden after wall removal and mesh warmup");ModelOcclusion.clear();if(ModelOcclusion.pending()!=0)throw new IllegalStateException("Queries retained after clear");System.out.println("[unpvp-lobby] PASS occlusion/name pixels/camera/removal/cleanup");mc.shutdown();since=0;return;}
   }else if(scene==0){populate();sample(Thread.currentThread(),dir);}else if(scene==1){mc.gameSettings.hideGUI=true;for(Entity e:entities)if(e instanceof EntityArmorStand){e.setAlwaysRenderNameTag(false);e.setCustomNameTag("");}}else{System.out.println("[unpvp-lobby] PASS");mc.shutdown();since=0;return;}scene++;frames.clear();measuring=false;last=0;since=System.nanoTime();
  }catch(Throwable e){e.printStackTrace();System.out.println("[unpvp-lobby] FAILED");mc.shutdown();since=0;}
 }
 private static void wall(boolean on){Minecraft mc=Minecraft.getMinecraft();for(int x=-12;x<=12;x++)for(int y=4;y<=11;y++)mc.theWorld.setBlockState(new net.minecraft.util.BlockPos(x,y,-3),(on?net.minecraft.init.Blocks.stone:net.minecraft.init.Blocks.air).getDefaultState(),3);}
 private static byte[] crop(){Minecraft mc=Minecraft.getMinecraft();int w=mc.displayWidth/2,h=mc.displayHeight/4;java.nio.ByteBuffer b=org.lwjgl.BufferUtils.createByteBuffer(w*h*4);org.lwjgl.opengl.GL11.glReadPixels(mc.displayWidth/4,mc.displayHeight/4,w,h,org.lwjgl.opengl.GL11.GL_RGBA,org.lwjgl.opengl.GL11.GL_UNSIGNED_BYTE,b);byte[] out=new byte[b.remaining()];b.get(out);return out;}
}
